-- R5F19: Superadmin-only roadmap with auditable status updates.
CREATE TABLE sdl_project_roadmap_records (
 id VARCHAR(32) PRIMARY KEY,
 section VARCHAR(16) NOT NULL CHECK(section IN ('roadmap','milestone','risk','version')),
 sort_order INTEGER NOT NULL CHECK(sort_order>0),
 payload JSONB NOT NULL CHECK(jsonb_typeof(payload)='array'),
 status VARCHAR(50) NOT NULL,
 management_note TEXT NOT NULL DEFAULT '' CHECK(length(management_note)<=1500),
 version BIGINT NOT NULL DEFAULT 1 CHECK(version>0),
 updated_by UUID REFERENCES sdl_users(id),
 updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX sdl_project_roadmap_records_order ON sdl_project_roadmap_records(section,sort_order);
CREATE TABLE sdl_project_roadmap_updates (
 id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 record_id VARCHAR(32) NOT NULL REFERENCES sdl_project_roadmap_records(id) ON DELETE RESTRICT,
 actor_id UUID NOT NULL REFERENCES sdl_users(id) ON DELETE RESTRICT,
 status_before VARCHAR(50) NOT NULL,
 status_after VARCHAR(50) NOT NULL,
 note TEXT NOT NULL DEFAULT '',
 created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX sdl_project_roadmap_updates_record ON sdl_project_roadmap_updates(record_id,created_at DESC);
CREATE TABLE sdl_project_roadmap_snapshots (
 day DATE PRIMARY KEY,
 completed INTEGER NOT NULL CHECK(completed>=0),
 total INTEGER NOT NULL CHECK(total>=completed AND total>0)
);
ON CONFLICT (id) DO NOTHING;
-- 23 October baseline is evidenced; historical values are not backfilled.
